import js from "@eslint/js";
import globals from "globals";
import reactHooks from "eslint-plugin-react-hooks";
import reactRefresh from "eslint-plugin-react-refresh";
import tseslint from "typescript-eslint";

export default tseslint.config(
  {
    // src/protocol/ is generated by ts-rs from the Rust types (`make
    // test-shared` rewrites it), so linting or formatting it only creates
    // churn that the next regeneration undoes.
    ignores: ["dist/", "src-tauri/", "src/protocol/"],
  },
  {
    files: ["**/*.{ts,tsx}"],
    extends: [js.configs.recommended, ...tseslint.configs.recommended],
    languageOptions: {
      ecmaVersion: 2022,
      globals: globals.browser,
    },
    plugins: {
      "react-hooks": reactHooks,
      "react-refresh": reactRefresh,
    },
    rules: {
      // Deliberately not `reactHooks.configs.recommended`: v7 folds in the
      // React Compiler rules (purity, immutability, set-state-in-render, ...),
      // which are a migration of their own rather than a lint pass. These two
      // are what the existing `eslint-disable-next-line` comments target.
      "react-hooks/rules-of-hooks": "error",
      "react-hooks/exhaustive-deps": "warn",
      "react-refresh/only-export-components": [
        "warn",
        { allowConstantExport: true },
      ],
    },
  },
  {
    // Config files and the Playwright suite run under Node, not in the webview.
    files: ["vite.config.ts", "playwright.config.ts", "tests-e2e/**/*.ts"],
    languageOptions: { globals: globals.node },
    rules: { "react-refresh/only-export-components": "off" },
  },
  {
    // vitest injects these (`globals: true` in vite.config.ts, `types:
    // ["vitest/globals"]` in tsconfig.json), though most tests import them too.
    files: ["src/**/*.test.{ts,tsx}"],
    languageOptions: { globals: { ...globals.vitest } },
  },
);
